  const crate=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M0 0L46 24 94 0V48L46 72 0 48Z" fill="#b98246" stroke="#775634" stroke-width="4" stroke-linejoin="round"/><path d="M46 24V72L94 48V0Z" fill="#996738"/><path d="M0 0L48 -24 94 0 46 24Z" fill="#ddb376" stroke="#98713e" stroke-width="4" stroke-linejoin="round"/><path d="M8 12L38 55M8 42L38 27M53 30L86 40M53 62L86 10M12 -4L79 7M33 -17L57 17" fill="none" stroke="#efc48b" stroke-width="5"/></g>`;
