 function islandVessel(room=false){const d=activeDelivery()||state.campaign.expedition,b=activeShip();let duration=60;if(state.fleet.job)duration=state.fleet.job.seconds;else if(state.growth.job)duration=growthContracts()[state.growth.job.slot].seconds;else if(state.factory.delivery)duration=tripQuote(d.order,d.route).seconds;else if(state.campaign.expedition)duration=destinations.find(x=>x.id===d.id).seconds;const elapsed=d?clamp(duration-(d.readyAt-Date.now())/1000,0,duration):0;return `<div class="island-vessel ${room?'drydock-vessel':d?'sailing-vessel':'moored-vessel'} fleet-vessel-${b.id} paint-${hulls.find(h=>h.id===state.vessel.hull).color}" style="--ship-scale:${b.scale};${!room&&d?`--journey:${duration}s;animation-delay:-${elapsed}s`:''}"><div class="vessel-assembly">${room&&!b.port?boatCradle():''}<img src="./${b.image}" alt="Din båd ${b.name} · ${b.type}" draggable="false">${islandBoatParts()}</div>${!room?'<div class="vessel-ripple"></div>':''}</div>`;}

 function islandDecorations(){return state.island.decor.map(d=>`<button class="island-decoration deco-${d.type}" data-place-key="d${d.id}" data-act="island-decoration" data-val="${d.id}" style="left:${d.x}px;top:${d.y}px;z-index:${d.y};--flip:${d.flip?-1:1}" aria-label="${islandDecor.find(c=>c.id===d.type).name}">${sceneryArt(d.type)}</button>`).join('');}
 function islandHUD(room=false){return `<div class="island-hud"><button class="captain-crest" data-act="tab" data-val="${room?'havn':'logbog'}" aria-label="${room?'Ud til havnen':'Åbn kaptajnsbogen'}"><span>${room?'←':'⚓'}</span><div><b>${room?'OTTO & KAPTAJNEN':'HAVNEKAPTAJNEN'}</b><small>${room?'Gør båden til din':'Din egen havn · etape '+num(state.growth.chapter)+' · v12.1.1'}</small></div></button><div class="island-wallet"><span class="coin-dot">●</span><b>${num(state.cash)}</b><span class="token-dot">⚓</span><b>${num(state.factory.tokens)}</b><button data-act="world-open" data-val="inventory" aria-label="Åbn lager">▦</button></div></div>`;}
